s("internal/is_prime_constexpr.hpp",{t({"namespace atcoder {","namespace internal {","","// Reference:","// M. Forisek and J. Jancina,","// Fast Primality Testing for Integers That Fit into a Machine Word","// @param n `0 <= n`","constexpr bool is_prime_constexpr(int n) {","  if (n <= 1) return false;","  if (n == 2 || n == 7 || n == 61) return true;","  if (n % 2 == 0) return false;","  long long d = n - 1;","  while (d % 2 == 0) d /= 2;","  constexpr long long bases[3] = {2, 7, 61};","  for (long long a : bases) {","    long long t = d;","    long long y = pow_mod_constexpr(a, t, n);","    while (t != n - 1 && y != 1 && y != n - 1) {","      y = y * y % n;","      t <<= 1;","    }","    if (y != n - 1 && t % 2 == 0) {","      return false;","    }","  }","  return true;","}","","}  // namespace internal","}  // namespace atcoder"})}),
s("internal/is_prime.hpp",{t({"namespace atcoder {","namespace internal {","","template <int n>","constexpr bool is_prime = is_prime_constexpr(n);","","}  // namespace internal","}  // namespace atcoder"})}),
