s("internal/pow_mod_constexpr.hpp",{t({"namespace atcoder {","namespace internal {","","// @param n `0 <= n`","// @param m `1 <= m`","// @return `(x ** n) % m`","constexpr long long pow_mod_constexpr(long long x, long long n, int m) {","  if (m == 1) return 0;","  unsigned int _m = (unsigned int) (m);","  unsigned long long r = 1;","  unsigned long long y = safe_mod(x, m);","  while (n) {","    if (n & 1) r = (r * y) % _m;","    y = (y * y) % _m;","    n >>= 1;","  }","  return r;","}","","}  // namespace internal","}  // namespace atcoder"})}),
s("internal/primitive_root_constexpr.hpp",{t({"namespace atcoder {","namespace internal {","","// Compile time primitive root","// @param m must be prime","// @return primitive root (and minimum in now)","constexpr int primitive_root_constexpr(int m) {","  if (m == 2) return 1;","  if (m == 167772161) return 3;","  if (m == 469762049) return 3;","  if (m == 754974721) return 11;","  if (m == 998244353) return 3;","  int divs[20] = {};","  divs[0] = 2;","  int cnt = 1;","  int x = (m - 1) / 2;","  while (x % 2 == 0) x /= 2;","  for (int i = 3; (long long) (i) *i <= x; i += 2) {","    if (x % i == 0) {","      divs[cnt++] = i;","      while (x % i == 0) {","        x /= i;","      }","    }","  }","  if (x > 1) {","    divs[cnt++] = x;","  }","  for (int g = 2;; g++) {","    bool ok = true;","    for (int i = 0; i < cnt; i++) {","      if (pow_mod_constexpr(g, (m - 1) / divs[i], m) == 1) {","        ok = false;","        break;","      }","    }","    if (ok) return g;","  }","}","","}  // namespace internal","}  // namespace atcoder"})}),
s("internal/primitive_root.hpp",{t({"namespace atcoder {","namespace internal {","","template <int m>","constexpr int primitive_root = primitive_root_constexpr(m);","","}  // namespace internal","}  // namespace atcoder"})}),
s("internal/safe_mod.hpp",{t({"namespace atcoder {","namespace internal {","","// @param m `1 <= m`","// @return x mod m","constexpr long long safe_mod(long long x, long long m) {","  x %= m;","  if (x < 0) x += m;","  return x;","}","","}  // namespace internal","}  // namespace atcoder"})}),
s("internal/scc_graph.hpp",{t({"namespace atcoder {","namespace internal {","","// Reference:","// R. Tarjan,","// Depth-First Search and Linear Graph Algorithms","struct scc_graph {"," public:","  explicit scc_graph(int n) : _n(n) {}","","  int num_vertices() { return _n; }","","  void add_edge(int from, int to) { edges.push_back({from, {to}}); }","","  // @return pair of (# of scc, scc id)","  std::pair<int, std::vector<int>> scc_ids() {","    auto g = csr<edge>(_n, edges);","    int now_ord = 0, group_num = 0;","    std::vector<int> visited, low(_n), ord(_n, -1), ids(_n);","    visited.reserve(_n);","    auto dfs = [&](auto self, int v) -> void {","      low[v] = ord[v] = now_ord++;","      visited.push_back(v);","      for (int i = g.start[v]; i < g.start[v + 1]; i++) {","        auto to = g.elist[i].to;","        if (ord[to] == -1) {","          self(self, to);","          low[v] = std::min(low[v], low[to]);","        } else {","          low[v] = std::min(low[v], ord[to]);","        }","      }","      if (low[v] == ord[v]) {","        while (true) {","          int u = visited.back();","          visited.pop_back();","          ord[u] = _n;","          ids[u] = group_num;","          if (u == v) break;","        }","        group_num++;","      }","    };","    for (int i = 0; i < _n; i++) {","      if (ord[i] == -1) dfs(dfs, i);","    }","    for (auto &x : ids) {","      x = group_num - 1 - x;","    }","    return {group_num, ids};","  }","","  std::vector<std::vector<int>> scc() {","    auto ids = scc_ids();","    int group_num = ids.first;","    std::vector<int> counts(group_num);","    for (auto x : ids.second) counts[x]++;","    std::vector<std::vector<int>> groups(ids.first);","    for (int i = 0; i < group_num; i++) {","      groups[i].reserve(counts[i]);","    }","    for (int i = 0; i < _n; i++) {","      groups[ids.second[i]].push_back(i);","    }","    return groups;","  }",""," private:","  int _n;","  struct edge {","    int to;","  };","  std::vector<std::pair<int, edge>> edges;","};","","}  // namespace internal","}  // namespace atcoder"})}),
s("internal/simple_queue.hpp",{t({"namespace atcoder {","namespace internal {","","template <class T>","struct simple_queue {","  std::vector<T> payload;","  int pos = 0;","  void reserve(int n) { payload.reserve(n); }","  int size() const { return int(payload.size()) - pos; }","  bool empty() const { return pos == int(payload.size()); }","  void push(const T &t) { payload.push_back(t); }","  T &front() { return payload[pos]; }","  void clear() {","    payload.clear();","    pos = 0;","  }","  void pop() { pos++; }","};","","}  // namespace internal","}  // namespace atcoder"})}),
