s("mat/mat_pow.hpp",{t({"template <class T>","std::vector<std::vector<T>> pow(std::vector<std::vector<T>> x, long long y) {","  assert(y >= 0);","  assert(x.size() == x[0].size());","  std::vector rv(x.size(), std::vector<T>(x.size(), 0));","  for (int i = 0; i < x.size(); i++) {","    rv[i][i] = 1;","  }","  for (; y; y >>= 1, x = matmul(x, x)) {","    if (y & 1) {","      rv = matmul(x, rv);","    }","  }","  return rv;","}"})}),
s("mat/matmul.hpp",{t({"template <class T>","std::vector<std::vector<T>> matmul(const std::vector<std::vector<T>> &a,","                                   const std::vector<std::vector<T>> &b) {","  assert(a[0].size() == b.size());","  std::vector rv(a.size(), std::vector<T>(b[0].size(), 0));","  for (int i = 0; i < a.size(); i++) {","    for (int j = 0; j < b[0].size(); j++) {","      for (int k = 0; k < a[0].size(); k++) {","        rv[i][j] += a[i][k] * b[k][j];","      }","    }","  }","  return rv;","}"})}),
s("misc/pratt_parser.hpp",{t({"// TODO: write pratt parser","//","// the way i understand it is that there's 3 main functions:","//","// 1. parse operand","// 2. parse operator","// 3. get binding power","//","// parsing operands is for parsing stuff that can't really be divided by an","// operator, so stuff like numbers, symbols, unary operators (negation, etc.),","// or parentheses","//","// parsing operators takes an lhs operand and an operator and calls a function","// to parse the rhs operand and then combines them as necessary","//","// binding power decides when to stop parsing for a subexpression. if an","// operator's binding power is too small, that means we can't use the operator","// just yet; we need to handle the higher binding power operators first. so i","// guess in simple terms, binding power is just \"what should i do first?\". i","// think left/right associativity comes into play when dealing with two binding","// powers that are equal","//","// i think we can implement this nicely with a stack? or cleaner with recursion?","//","// i think operand and operator parsing are forced to have access to the parsing","// context to handle stuff with trailing tokens like parentheses or functions","//","// honestly though, i feel like trailing tokens aren't that big a deal because","// they don't provide any new information. i believe we can make these a no-op,","// at least for what a pratt parser is supposed to provide"})}),
s("misc/viz.hpp",{t({"#ifdef ETHANKIM8683","void viz(const std::function<void()> &draw) {","  static bool init = true;","  if (init) {","    SetTraceLogLevel(LOG_NONE);","    SetTargetFPS(30);","    init = false;","  }","","  InitWindow(400, 400, \"\");","  BeginDrawing();","  draw();","  EndDrawing();","  while (!WindowShouldClose()) {","    PollInputEvents();","  }","  CloseWindow();","}","#else","#define viz(...)","#endif"})}),
s("modint/dynamic_modint.hpp",{t({"namespace atcoder {","","template <int id>","struct dynamic_modint : internal::modint_base {","  using mint = dynamic_modint;",""," public:","  static int mod() { return (int) (bt.umod()); }","  static void set_mod(int m) {","    assert(1 <= m);","    bt = internal::barrett(m);","  }","  static mint raw(int v) {","    mint x;","    x._v = v;","    return x;","  }","","  dynamic_modint() : _v(0) {}","  template <class T, internal::is_signed_int_t<T> * = nullptr>","  dynamic_modint(T v) {","    long long x = (long long) (v % (long long) (mod()));","    if (x < 0) x += mod();","    _v = (unsigned int) (x);","  }","  template <class T, internal::is_unsigned_int_t<T> * = nullptr>","  dynamic_modint(T v) {","    _v = (unsigned int) (v % mod());","  }","","  unsigned int val() const { return _v; }","","  mint &operator++() {","    _v++;","    if (_v == umod()) _v = 0;","    return *this;","  }","  mint &operator--() {","    if (_v == 0) _v = umod();","    _v--;","    return *this;","  }","  mint operator++(int) {","    mint result = *this;","    ++*this;","    return result;","  }","  mint operator--(int) {","    mint result = *this;","    --*this;","    return result;","  }","","  mint &operator+=(const mint &rhs) {","    _v += rhs._v;","    if (_v >= umod()) _v -= umod();","    return *this;","  }","  mint &operator-=(const mint &rhs) {","    _v += mod() - rhs._v;","    if (_v >= umod()) _v -= umod();","    return *this;","  }","  mint &operator*=(const mint &rhs) {","    _v = bt.mul(_v, rhs._v);","    return *this;","  }","  mint &operator/=(const mint &rhs) { return *this = *this * rhs.inv(); }","","  mint operator+() const { return *this; }","  mint operator-() const { return mint() - *this; }","","  mint pow(long long n) const {","    assert(0 <= n);","    mint x = *this, r = 1;","    while (n) {","      if (n & 1) r *= x;","      x *= x;","      n >>= 1;","    }","    return r;","  }","  mint inv() const {","    auto eg = internal::inv_gcd(_v, mod());","    assert(eg.first == 1);","    return eg.second;","  }","","  friend mint operator+(const mint &lhs, const mint &rhs) {","    return mint(lhs) += rhs;","  }","  friend mint operator-(const mint &lhs, const mint &rhs) {","    return mint(lhs) -= rhs;","  }","  friend mint operator*(const mint &lhs, const mint &rhs) {","    return mint(lhs) *= rhs;","  }","  friend mint operator/(const mint &lhs, const mint &rhs) {","    return mint(lhs) /= rhs;","  }","  friend bool operator==(const mint &lhs, const mint &rhs) {","    return lhs._v == rhs._v;","  }","  friend bool operator!=(const mint &lhs, const mint &rhs) {","    return lhs._v != rhs._v;","  }",""," private:","  unsigned int _v;","  static internal::barrett bt;","  static unsigned int umod() { return bt.umod(); }","};","template <int id>","internal::barrett dynamic_modint<id>::bt(998244353);","","}  // namespace atcoder"})}),
