s("modint/static_modint.hpp",{t({"namespace atcoder {","","template <int m, std::enable_if_t<(1 <= m)> * = nullptr>","struct static_modint : internal::static_modint_base {","  using mint = static_modint;",""," public:","  static constexpr int mod() { return m; }","  static mint raw(int v) {","    mint x;","    x._v = v;","    return x;","  }","","  static_modint() : _v(0) {}","  template <class T, internal::is_signed_int_t<T> * = nullptr>","  static_modint(T v) {","    long long x = (long long) (v % (long long) (umod()));","    if (x < 0) x += umod();","    _v = (unsigned int) (x);","  }","  template <class T, internal::is_unsigned_int_t<T> * = nullptr>","  static_modint(T v) {","    _v = (unsigned int) (v % umod());","  }","","  unsigned int val() const { return _v; }","","  mint &operator++() {","    _v++;","    if (_v == umod()) _v = 0;","    return *this;","  }","  mint &operator--() {","    if (_v == 0) _v = umod();","    _v--;","    return *this;","  }","  mint operator++(int) {","    mint result = *this;","    ++*this;","    return result;","  }","  mint operator--(int) {","    mint result = *this;","    --*this;","    return result;","  }","","  mint &operator+=(const mint &rhs) {","    _v += rhs._v;","    if (_v >= umod()) _v -= umod();","    return *this;","  }","  mint &operator-=(const mint &rhs) {","    _v -= rhs._v;","    if (_v >= umod()) _v += umod();","    return *this;","  }","  mint &operator*=(const mint &rhs) {","    unsigned long long z = _v;","    z *= rhs._v;","    _v = (unsigned int) (z % umod());","    return *this;","  }","  mint &operator/=(const mint &rhs) { return *this = *this * rhs.inv(); }","","  mint operator+() const { return *this; }","  mint operator-() const { return mint() - *this; }","","  mint pow(long long n) const {","    assert(0 <= n);","    mint x = *this, r = 1;","    while (n) {","      if (n & 1) r *= x;","      x *= x;","      n >>= 1;","    }","    return r;","  }","  mint inv() const {","    if (prime) {","      assert(_v);","      return pow(umod() - 2);","    } else {","      auto eg = internal::inv_gcd(_v, m);","      assert(eg.first == 1);","      return eg.second;","    }","  }","","  friend mint operator+(const mint &lhs, const mint &rhs) {","    return mint(lhs) += rhs;","  }","  friend mint operator-(const mint &lhs, const mint &rhs) {","    return mint(lhs) -= rhs;","  }","  friend mint operator*(const mint &lhs, const mint &rhs) {","    return mint(lhs) *= rhs;","  }","  friend mint operator/(const mint &lhs, const mint &rhs) {","    return mint(lhs) /= rhs;","  }","  friend bool operator==(const mint &lhs, const mint &rhs) {","    return lhs._v == rhs._v;","  }","  friend bool operator!=(const mint &lhs, const mint &rhs) {","    return lhs._v != rhs._v;","  }",""," private:","  unsigned int _v;","  static constexpr unsigned int umod() { return m; }","  static constexpr bool prime = internal::is_prime<m>;","};","","}  // namespace atcoder"})}),
s("string/SuffixArray.hpp",{t({"struct SuffixArray {","  vi sa, lcp;","  SuffixArray(string &s, int lim = 256) {  // or basic_string<int>","    int n = sz(s) + 1, k = 0, a, b;","    vi x(all(s)), y(n), ws(max(n, lim));","    x.pb(0), sa = lcp = y, iota(all(sa), 0);","    for (int j = 0, p = 0; p < n; j = max(1ll, j * 2), lim = p) {","      p = j, iota(all(y), n - j);","      rep(i, 0, n) if (sa[i] >= j) y[p++] = sa[i] - j;","      fill(all(ws), 0);","      rep(i, 0, n) ws[x[i]]++;","      rep(i, 1, lim) ws[i] += ws[i - 1];","      for (int i = n; i--;) sa[--ws[x[y[i]]]] = y[i];","      swap(x, y), p = 1, x[sa[0]] = 0;","      rep(i, 1, n) a = sa[i - 1], b = sa[i],","                   x[b] = (y[a] == y[b] && y[a + j] == y[b + j]) ? p - 1 : p++;","    }","    for (int i = 0, j; i < n - 1; lcp[x[i++]] = k)","      for (k &&k--, j = sa[x[i] - 1]; s[i + k] == s[j + k]; k++);","  }","};"})}),
s("string/z_algorithm.hpp",{t({"namespace atcoder {","","// Reference:","// D. Gusfield,","// Algorithms on Strings, Trees, and Sequences: Computer Science and","// Computational Biology","template <class T>","std::vector<int> z_algorithm(const std::vector<T> &s) {","  int n = int(s.size());","  if (n == 0) return {};","  std::vector<int> z(n);","  z[0] = 0;","  for (int i = 1, j = 0; i < n; i++) {","    int &k = z[i];","    k = (j + z[j] <= i) ? 0 : std::min(j + z[j] - i, z[i - j]);","    while (i + k < n && s[k] == s[i + k]) k++;","    if (j + z[j] < i + z[i]) j = i;","  }","  z[0] = n;","  return z;","}","","std::vector<int> z_algorithm(const std::string &s) {","  int n = int(s.size());","  std::vector<int> s2(n);","  for (int i = 0; i < n; i++) {","    s2[i] = s[i];","  }","  return z_algorithm(s2);","}","","}  // namespace atcoder"})}),
s("traits/double_width.hpp",{t({"// https://stackoverflow.com/a/38853594/19662543","template <class T>","struct double_width;","template <>","struct double_width<char> : type_container<short> {};","template <>","struct double_width<short> : type_container<int> {};","template <>","struct double_width<int> : type_container<long long> {};","template <>","struct double_width<long> : type_container<long long> {};","template <>","struct double_width<long long> : type_container<__int128> {};","template <>","struct double_width<unsigned char> : type_container<unsigned short> {};","template <>","struct double_width<unsigned short> : type_container<unsigned int> {};","template <>","struct double_width<unsigned int> : type_container<unsigned long long> {};","template <>","struct double_width<unsigned long> : type_container<unsigned long long> {};","template <>","struct double_width<unsigned long long> : type_container<unsigned __int128> {};","template <>","struct double_width<float> : type_container<double> {};","template <>","struct double_width<double> : type_container<long double> {};","template <int MOD>","struct double_width<atcoder::static_modint<MOD>>","    : type_container<atcoder::static_modint<MOD>> {};","template <int ID>","struct double_width<atcoder::dynamic_modint<ID>>","    : type_container<atcoder::dynamic_modint<ID>> {};","template <class T>","using double_width_t = typename double_width<T>::type;"})}),
